class Solution:
    def maximumScore(self, nums1, nums2):
        s1, s2 = sum(nums1), sum(nums2)
        def kadane(d):
            cur = best = 0
            for x in d:
                cur = max(cur + x, 0)
                best = max(best, cur)
            return best
        d = [a - b for a, b in zip(nums1, nums2)]
        return max(s1, s2, s2 + kadane(d), s1 + kadane([-x for x in d]))

