class Solution {
    long long kadane(vector<long long>& d) {
        long long cur = 0, best = 0;
        for (long long x : d) {
            cur = max(cur + x, 0LL);
            best = max(best, cur);
        }
        return best;
    }
public:
    int maximumScore(vector<int>& nums1, vector<int>& nums2) {
        long long s1 = accumulate(nums1.begin(), nums1.end(), 0LL);
        long long s2 = accumulate(nums2.begin(), nums2.end(), 0LL);
        vector<long long> d, nd;
        for (int i = 0; i < (int)nums1.size(); i++) {
            d.push_back(nums1[i] - nums2[i]);
            nd.push_back(nums2[i] - nums1[i]);
        }
        return (int)max({s1, s2, s2 + kadane(d), s1 + kadane(nd)});
    }
};

