class Solution {
    private long kadane(long[] d) {
        long cur = 0, best = 0;
        for (long x : d) {
            cur = Math.max(cur + x, 0);
            best = Math.max(best, cur);
        }
        return best;
    }
    public int maximumScore(int[] nums1, int[] nums2) {
        long s1 = 0, s2 = 0;
        int n = nums1.length;
        long[] d = new long[n], nd = new long[n];
        for (int i = 0; i < n; i++) {
            s1 += nums1[i]; s2 += nums2[i];
            d[i] = nums1[i] - nums2[i];
            nd[i] = -d[i];
        }
        return (int) Math.max(Math.max(s1, s2), Math.max(s2 + kadane(d), s1 + kadane(nd)));
    }
}

