    const kadane = d => {
        let cur = 0, best = 0;
        for (const x of d) { cur = Math.max(cur + x, 0); best = Math.max(best, cur); }
        return best;
    };
    const s1 = nums1.reduce((a, b) => a + b, 0);
    const s2 = nums2.reduce((a, b) => a + b, 0);
    const d = nums1.map((a, i) => a - nums2[i]);
    return Math.max(s1, s2, s2 + kadane(d), s1 + kadane(d.map(x => -x)));
};

